#include <iostream>
#include <array>
#include <vector>
#include <algorithm>
#include <iterator>

bool greater9(int value) {
    return value > 9;
}

int main() {
    std::array<int, 10> a1 = {10, 2, 10, 4, 16, 6, 14, 8, 12, 10};
    std::ostream_iterator<int> output(std::cout, " ");

    // 1. In-place replace: replace 10 with 100
    std::replace(a1.begin(), a1.end(), 10, 100);
    std::cout << "a1 after replace(10 -> 100): ";
    std::copy(a1.cbegin(), a1.cend(), output);
    std::cout << "\n";

    // 2. In-place replace_if: replace values > 9 with 0
    std::replace_if(a1.begin(), a1.end(), greater9, 0);
    std::cout << "a1 after replace_if(>9 -> 0): ";
    std::copy(a1.cbegin(), a1.cend(), output);
    std::cout << "\n";

    // 3. Out-of-place replace_copy_if
    std::vector<int> src = {5, 12, 7, 20, 3};
    std::vector<int> dest(src.size());
    auto endIt = std::replace_copy_if(src.cbegin(), src.cend(), dest.begin(), greater9, 99);
    std::cout << "dest after replace_copy_if(>9 -> 99): ";
    std::copy(dest.begin(), endIt, output);
    std::cout << "\n";

    return 0;
}

#include <iostream>
#include <array>
#include <algorithm>
#include <numeric>

int main() {
    std::array<int, 10> a2 = {100, 2, 8, 1, 50, 3, 8, 8, 9, 10};

    // 1. count and count_if
    int count8 = std::count(a2.cbegin(), a2.cend(), 8);
    int countGt9 = std::count_if(a2.cbegin(), a2.cend(), [](int x) { return x > 9; });
    std::cout << "Count 8: " << count8 << "\n";
    std::cout << "Count > 9: " << countGt9 << "\n";

    // 2. min_element, max_element, and minmax_element
    auto minIt = std::min_element(a2.cbegin(), a2.cend());
    auto maxIt = std::max_element(a2.cbegin(), a2.cend());
    if (minIt != a2.cend() && maxIt != a2.cend()) {
        std::cout << "Min: " << *minIt << ", Max: " << *maxIt << "\n";
    }

    auto minAndMax = std::minmax_element(a2.cbegin(), a2.cend());
    std::cout << "minmax_element: " << *minAndMax.first << " and " << *minAndMax.second << "\n";

    // 3. accumulate: default sum
    int sum = std::accumulate(a2.cbegin(), a2.cend(), 0);
    std::cout << "Total sum: " << sum << "\n";

    // 4. accumulate: 4-argument custom binary operator (product)
    std::array<int, 4> small = {1, 2, 3, 4};
    int product = std::accumulate(small.cbegin(), small.cend(), 1, [](int acc, int val) {
        return acc * val;
    });
    std::cout << "Product: " << product << "\n";

    return 0;
}

#include <iostream>
#include <vector>
#include <array>
#include <algorithm>
#include <iterator>

int calculateCube(int x) {
    return x * x * x;
}

int main() {
    std::array<int, 5> a = {1, 2, 3, 4, 5};
    std::ostream_iterator<int> output(std::cout, " ");

    // 1. for_each with side-effect (printing squares)
    std::cout << "Squares via for_each: ";
    std::for_each(a.cbegin(), a.cend(), [](int x) {
        std::cout << (x * x) << " ";
    });
    std::cout << "\n";

    // 2. Unary transform: compute cube of each element
    std::vector<int> cubes(a.size());
    std::transform(a.cbegin(), a.cend(), cubes.begin(), calculateCube);
    std::cout << "Cubes via unary transform: ";
    std::copy(cubes.cbegin(), cubes.cend(), output);
    std::cout << "\n";

    // 3. Binary transform: element-wise sum of two containers
    std::array<int, 5> b = {10, 20, 30, 40, 50};
    std::vector<int> sums(a.size());
    std::transform(a.cbegin(), a.cend(), b.cbegin(), sums.begin(), [](int x, int y) {
        return x + y;
    });
    std::cout << "Sums via binary transform: ";
    std::copy(sums.cbegin(), sums.cend(), output);
    std::cout << "\n";

    return 0;
}
